cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>
#include <type_traits>
using namespace cute;
template <typename T>
__global__ void ln_partial_kernel(
    const T* __restrict__ X,
    double* __restrict__ partial_sum,
    double* __restrict__ partial_sumsq,
    int N, int M, int chunkCount, int chunkSize, bool vec4)
{
    constexpr int Threads = 256;
    int n   = blockIdx.x;
    int c   = blockIdx.y;
    int tid = threadIdx.x;
    if (n >= N || c >= chunkCount) return;
    int start = c * chunkSize;
    int end   = start + chunkSize;
    if (end > M) end = M;
    if (start >= end) {
        if (tid == 0) {
            partial_sum[(int64_t)n * chunkCount + c]   = 0.0;
            partial_sumsq[(int64_t)n * chunkCount + c] = 0.0;
        }
        return;
    }
    const T* row = X + (int64_t)n * M;
    double sum   = 0.0;
    double sumsq = 0.0;
    if (vec4 && std::is_same<T, float>::value) {
        const float4* row4 = reinterpret_cast<const float4*>(row);
        int len = end - start;
        int vecIters = len / (Threads * 4);
        int vecLen = vecIters * Threads * 4;
        int vecEnd = start + vecLen;
        for (int i = start + tid * 4; i < vecEnd; i += Threads * 4) {
            float4 v4 = row4[i >> 2];
            double a = (double)v4.x, b = (double)v4.y, cc = (double)v4.z, d = (double)v4.w;
            sum   += a + b + cc + d;
            sumsq += a * a + b * b + cc * cc + d * d;
        }
        for (int i = vecEnd + tid; i < end; i += Threads) {
            double v = static_cast<double>(row[i]);
            sum   += v;
            sumsq += v * v;
        }
    } else {
        for (int i = start + tid; i < end; i += Threads) {
            double v = static_cast<double>(row[i]);
            sum   += v;
            sumsq += v * v;
        }
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    __shared__ double s_sum[Threads / 32];
    __shared__ double s_sumsq[Threads / 32];
    int warpId = tid >> 5;
    int lane   = tid & 31;
    if (lane == 0) {
        s_sum[warpId]   = sum;
        s_sumsq[warpId] = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        double total_sum = 0.0, total_sumsq = 0.0;
        #pragma unroll
        for (int w = 0; w < Threads / 32; ++w) {
            total_sum   += s_sum[w];
            total_sumsq += s_sumsq[w];
        }
        partial_sum[(int64_t)n * chunkCount + c]   = total_sum;
        partial_sumsq[(int64_t)n * chunkCount + c] = total_sumsq;
    }
}
__global__ void ln_finalize_kernel(
    const double* __restrict__ partial_sum,
    const double* __restrict__ partial_sumsq,
    double* __restrict__ mean_out,
    double* __restrict__ invstd_out,
    int N, int M, int chunkCount, float eps)
{
    constexpr int Threads = 256;
    int n = blockIdx.x;
    if (n >= N) return;
    int tid = threadIdx.x;
    double sum   = 0.0;
    double sumsq = 0.0;
    for (int c = tid; c < chunkCount; c += Threads) {
        sum   += partial_sum[(int64_t)n * chunkCount + c];
        sumsq += partial_sumsq[(int64_t)n * chunkCount + c];
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    __shared__ double s_sum[Threads / 32];
    __shared__ double s_sumsq[Threads / 32];
    int warpId = tid >> 5;
    int lane   = tid & 31;
    if (lane == 0) {
        s_sum[warpId]   = sum;
        s_sumsq[warpId] = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        double total_sum = 0.0, total_sumsq = 0.0;
        #pragma unroll
        for (int w = 0; w < Threads / 32; ++w) {
            total_sum   += s_sum[w];
            total_sumsq += s_sumsq[w];
        }
        double mean = total_sum / (double)M;
        double var  = total_sumsq / (double)M - mean * mean;
        if (var < 0.0) var = 0.0;
        double invstd = 1.0 / sqrt(var + (double)eps);
