template <typename T>
__global__ void ln_normalize_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Gamma,
    const T* __restrict__ Beta,
    T* __restrict__ Y,
    const double* __restrict__ mean_in,
    const double* __restrict__ invstd_in,
    int N, int M, int chunkCount, int chunkSize, bool vec4)
{
    constexpr int Threads = 256;
    int n   = blockIdx.x;
    int c   = blockIdx.y;
    int tid = threadIdx.x;
    if (n >= N || c >= chunkCount) return;
    int start = c * chunkSize;
    int end   = start + chunkSize;
    if (end > M) end = M;
    if (start >= end) return;
    const T* rowX = X + (int64_t)n * M;
    T* rowY = Y + (int64_t)n * M;
    double mean   = mean_in[n];
    double invstd = invstd_in[n];
    if (vec4 && std::is_same<T, float>::value) {
        const float4* rowX4 = reinterpret_cast<const float4*>(rowX);
        const float4* gamma4 = reinterpret_cast<const float4*>(Gamma);
        const float4* beta4  = reinterpret_cast<const float4*>(Beta);
        float4* rowY4 = reinterpret_cast<float4*>(rowY);
        int len = end - start;
        int vecIters = len / (Threads * 4);
        int vecLen = vecIters * Threads * 4;
        int vecEnd = start + vecLen;
        for (int i = start + tid * 4; i < vecEnd; i += Threads * 4) {
            int idx4 = i >> 2;
            float4 xv = rowX4[idx4];
            float4 gv = gamma4[idx4];
            float4 bv = beta4[idx4];
            float4 outv;
            outv.x = (float)(((double)xv.x - mean) * invstd * (double)gv.x + (double)bv.x);
            outv.y = (float)(((double)xv.y - mean) * invstd * (double)gv.y + (double)bv.y);
            outv.z = (float)(((double)xv.z - mean) * invstd * (double)gv.z + (double)bv.z);
            outv.w = (float)(((double)xv.w - mean) * invstd * (double)gv.w + (double)bv.w);
            rowY4[idx4] = outv;
        }
        for (int i = vecEnd + tid; i < end; i += Threads) {
            double v = static_cast<double>(rowX[i]);
            double g = static_cast<double>(Gamma[i]);
            double b = static_cast<double>(Beta[i]);
            double out = (v - mean) * invstd * g + b;
            rowY[i] = static_cast<T>(out);
        }
    } else {
        for (int i = start + tid; i < end; i += Threads) {
            double v = static_cast<double>(rowX[i]);
            double g = static_cast<double>(Gamma[i]);
            double b = static_cast<double>(Beta[i]);
            double out = (v - mean) * invstd * g + b;
            rowY[i] = static_cast<T>(out);
        }
    }
}
torch::Tensor cute_layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be CUDA");
    TORCH_CHECK(beta.is_cuda(), "beta must be CUDA");
    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();
    int64_t normalized_ndim = gamma_c.dim();
    int64_t M = 1;
    for (int64_t i = 0; i < normalized_ndim; ++i) {
        M *= gamma_c.size(i);
    }
    int64_t total = x_c.numel();
    TORCH_CHECK(total % M == 0, "input numel not divisible by normalized_shape numel");
    int64_t N = total / M;
    auto y = torch::empty_like(x_c);
    constexpr int Threads = 256;
    // Determine chunk count per row so the grid has enough blocks to
    // fully occupy the GPU even when N (number of normalized rows) is small.
    // Query the device's SM count so we can size the grid to fully saturate
    // the GPU (the previous fixed value of 256 severely under-utilized
    // devices with many SMs and large per-row reduction workloads,
    // leading to low achieved occupancy).
    int device_idx = x_c.device().index();
    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device_idx);
    int64_t smCount = (int64_t)std::max(prop.multiProcessorCount, 1);
    // Aim for a healthy number of blocks per SM to keep the scheduler busy
    // while still leaving enough work per block to amortize the
    // block-level reduction overhead.
    int64_t desiredTotalBlocks = smCount * 32;
    int64_t perRow = (desiredTotalBlocks + std::max<int64_t>(N, 1) - 1) / std::max<int64_t>(N, 1);
    if (perRow < 1) perRow = 1;
    int64_t maxChunksByM = std::max<int64_t>(1, M / Threads);
    int64_t chunkCount64 = std::min<int64_t>(perRow, maxChunksByM);
    if (chunkCount64 < 1) chunkCount64 = 1;
    int chunkCount = (int)chunkCount64;
    int chunkSize = (int)((M + chunkCount - 1) / chunkCount);
    // Round chunkSize up to a multiple of 4 so that per-row chunk start
    // offsets stay 16-byte aligned, enabling safe float4 vectorized
    // memory accesses for the reduction/normalize kernels.
    chunkSize = ((chunkSize + 3) / 4) * 4;
    bool vec4 = (x_c.scalar_type() == torch::kFloat) && (M % 4 == 0);
    auto opts_d = torch::TensorOptions().dtype(torch::kFloat64).device(x_c.device());
    auto partial_sum   = torch::empty({N * (int64_t)chunkCount}, opts_d);
    auto partial_sumsq = torch::empty({N * (int64_t)chunkCount}, opts_d);
    auto mean_t   = torch::empty({N}, opts_d);
    auto invstd_t = torch::empty({N}, opts_d);
    dim3 grid_reduce((unsigned)N, (unsigned)chunkCount);
    dim3 block(Threads);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "cute_layernorm_forward", ([&] {
        ln_partial_kernel<scalar_t><<<grid_reduce, block, 0, stream>>>(
            x_c.data_ptr<scalar_t>(),
            partial_sum.data_ptr<double>(),
            partial_sumsq.data_ptr<double>(),
            (int)N, (int)M, chunkCount, chunkSize, vec4
        );
        ln_finalize_kernel<<<(unsigned)N, Threads, 0, stream>>>(
            partial_sum.data_ptr<double>(),
            partial_sumsq.data_ptr<double>(),
            mean_t.data_ptr<double>(),
            invstd_t.data_ptr<double>(),
            (int)N, (int)M, chunkCount, (float)eps
        );
        ln_normalize_kernel<scalar_t><<<grid_reduce, block, 0, stream>>>(
            x_c.data_ptr<scalar_t>(),
            gamma_c.data_ptr<scalar_t>(),
            beta_c.data_ptr<scalar_t>(),
            y.data_ptr<scalar_t>(),
            mean_t.data_ptr<double>(),
            invstd_t.data_ptr<double>(),
            (int)N, (int)M, chunkCount, chunkSize, vec4
        );
    }));
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUTE/CUDA kernel that fuses
    mean/variance computation and the affine normalization.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(
            x, self.weight, self.bias, float(self.eps)
        )

